"""Package actual WebGL comparisons and measured results for feature review."""
from hashlib import sha256
import json
from pathlib import Path
import shutil

from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs/quality-report'
before = json.loads((OUT/'before.json').read_text(encoding='utf-8'))
after = json.loads((OUT/'after.json').read_text(encoding='utf-8'))
assert before['result'] == after['result'] == 'passed'
assert after['htmlSha256'] == sha256((ROOT/'docs/index.html').read_bytes()).hexdigest(), 'Capture the current viewer before building its report'
checks = {}
for name, filename in [('render', 'v15-render-quality.json'), ('compatibility', 'v15-mobile-compatibility.json'), ('resources', 'v15-resource-policy.json'), ('decor', 'v15-decor-validation.json')]:
    source = ROOT/'validation'/filename
    data = json.loads(source.read_text(encoding='utf-8'))
    assert data.get('result') == 'passed' if name != 'decor' else not data['errors']
    checks[name] = {'file': filename, 'scope': data.get('scope'), 'result': 'passed'}
    shutil.copyfile(source, OUT/filename)

for report in (before, after):
    for case in report['cases']:
        for shot in case['shots']:
            source = OUT/shot['file']
            target = source.with_suffix('.webp')
            if source.suffix == '.png':
                image = Image.open(source).convert('RGB')
                image.thumbnail((1600, 1800), Image.Resampling.LANCZOS)
                image.save(target, 'WEBP', quality=92, method=6)
                shot['file'] = target.name
    (OUT/(report['stage']+'.json')).write_text(json.dumps(report, indent=2)+'\n', encoding='utf-8')

assets = json.loads((ROOT/'src/quality-assets.json').read_text(encoding='utf-8'))
desktop_mib, mobile_mib = (assets['texels'][kind]*4/2**20 for kind in ('desktop','mobile'))
resource = {'desktopMiB':desktop_mib, 'mobileMiB':mobile_mib, 'savingPercent':100*(1-mobile_mib/desktop_mib), 'htmlBytes':len((ROOT/'docs/index.html').read_bytes()), 'baselineHtmlBytes':len((ROOT/'work/render-quality/baseline.html').read_bytes())}
data = json.dumps({'before':before, 'after':after, 'resources':resource}, ensure_ascii=False).replace('</', '<\\/')
page = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>V15 画质提升 · PC / 手机效果报告</title><style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#263b34;background:#f3f5f1;line-height:1.7}*{box-sizing:border-box}body{margin:0}main{max-width:1152px;margin:auto;padding:46px 28px 64px}a{color:#23694f}h1{font-size:clamp(27px,4vw,42px);line-height:1.25;margin:12px 0 18px;letter-spacing:-1px}h2{font-size:22px;margin:28px 0 12px}h3{font-size:17px;margin:8px 0}p{margin:10px 0}.eyebrow{font-size:12px;letter-spacing:2px;color:#527565}.lede{max-width:800px;color:#53685e}.links{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}.links a{padding:9px 15px;border:1px solid #cbd8cf;border-radius:7px;text-decoration:none;background:#fff}.links a:first-child{background:#286b51;color:#fff}.notice{padding:14px 18px;background:#e8eee5;border-left:3px solid #688e5d;border-radius:4px;font-size:14px;margin:20px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card{background:#fff;border:1px solid #dce3da;border-radius:10px;padding:18px}.card b{display:block;font-size:27px;font-weight:600;color:#286b51}.small{font-size:12px;color:#65766b}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{font:inherit;border:1px solid #cbd7cd;background:white;padding:9px 17px;border-radius:6px;cursor:pointer;color:#3b5146}button[aria-pressed=true]{background:#286b51;color:#fff;border-color:#286b51}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #c6963b;outline-offset:3px}.comparison{position:relative;width:100%;background:#18221d;border-radius:9px;overflow:hidden;--split:50%}.comparison img{display:block;width:100%;height:auto}.comparison .old{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--split)) 0 0)}.comparison .old img{width:100%;height:100%;object-fit:fill}.comparison:after{content:"";position:absolute;left:var(--split);top:0;bottom:0;width:2px;background:#fff9;pointer-events:none}.comparison.mobile{max-width:390px;margin:auto}.labels{position:absolute;left:12px;right:12px;top:12px;display:flex;justify-content:space-between;pointer-events:none;z-index:1}.labels span{background:#14271ecc;color:white;border-radius:4px;padding:4px 10px;font-size:12px}.range{display:flex;align-items:center;gap:16px;margin:14px 0;font-size:13px}.range input{flex:1;accent-color:#286b51;min-width:70px}.caption{font-size:13px;color:#617368;margin:8px 0 20px}.table-wrap{overflow:auto;border:1px solid #d6dfd3;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px;background:#fff}td,th{text-align:left;padding:11px 15px;border-bottom:1px solid #e1e7dd;white-space:nowrap}th{background:#eaf0e5;font-weight:600}tr:last-child td{border:0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.checks{padding-left:22px}footer{margin-top:32px;border-top:1px solid #d6dfd3;padding-top:20px;font-size:12px;color:#65766b}code{background:#e6ece2;padding:2px 5px;border-radius:3px;overflow-wrap:anywhere}.pill{font-size:12px;border:1px solid #c9d6c9;padding:3px 8px;border-radius:20px;display:inline-block}details{margin:12px 0}summary{cursor:pointer}ul{padding-left:22px}@media(max-width:600px){main{padding:28px 17px 45px}.cards{grid-template-columns:1fr}.card{padding:12px 16px}.card b{font-size:24px}.columns{grid-template-columns:1fr;gap:4px}.links a{font-size:13px}.range{gap:9px}.small{font-size:12px}}
</style></head><body><main><div class="eyebrow">杭州 · 璞荟铭庭 / FEATURE REVIEW</div><h1>画质提升 · 首轮效果报告</h1><span class="pill">feature/render-quality · V15</span><p class="lede">对比材质、家具受光与移动端资源预算。所有画面来自实际网页 WebGL 画布，同机位、同视野角度采集；本轮沿用现有建筑烘焙。</p><nav class="links"><a href="../?decor=a">打开画质测试页</a><a href="../?verify=mobile">在本机微信 / 浏览器检测</a><a href="../deployment.json">查看部署提交</a></nav><div class="notice"><strong>验证边界：</strong>PC 与手机视口截图均在 Windows + Chrome、NVIDIA RTX 5080 上采集。手机视口、触控、微信 UA 和 Windows WebKit 检查不等于物理手机或手机微信测试。帧率受 60 / 约 30 FPS 上限限制，不能据此推断手机帧率提升。</div><div class="cards"><div class="card"><span>手机烘焙纹理基础层估算</span><b id="memory"></b><span class="small">RGBA8 等效，不包含其他贴图、缓存与缓冲；不是显存实测</span></div><div class="card"><span>对比场景</span><b>PC + 手机 · 各 4 组</b><span class="small">客厅昼夜、主卧白天、毛坯白天</span></div><div class="card"><span>手机反射缓存</span><b>最多 2 个房间</b><span class="small">静止后刷新；高负载降低分辨率，负载恢复后逐步提高</span></div></div><h2>同机位前后对比</h2><div class="tabs" id="devices"><button data-device="pc">PC · 1280 × 800</button><button data-device="mobile">手机视口 · 390 × 844</button></div><div class="tabs" id="scenes"></div><div id="comparison" class="comparison"><img id="newImage" alt="优化后实际网页画面"><div class="old"><img id="oldImage" alt="优化前实际网页画面"></div><div class="labels"><span>优化前 · V14.2</span><span>优化后 · V15</span></div></div><label class="range">优化前<input id="split" aria-label="调整前后画面对比" type="range" min="0" max="100" value="50">优化后</label><p class="caption" id="caption"></p><h2>本机观测数据</h2><p class="small">每场景静止后采样约 2.2 秒，统计实际渲染帧数；启动时间从本机 HTTP 导航计到默认毛坯启动及 219 张纹理加载完成，单次测量不代表公网下载速度或稳定性能。手机自动分辨率会随运行负载变化。</p><div class="table-wrap"><table><thead><tr><th>设备 / 场景</th><th>优化前 FPS</th><th>优化后 FPS</th><th>前 → 后画布</th></tr></thead><tbody id="metrics"></tbody></table></div><p id="boot" class="small"></p><div class="columns"><section><h2>本轮已实现</h2><ul><li>颜色、凹凸、粗糙度分离；统一木材、织物、石材和水泥细节。</li><li>从现有建筑烘焙生成 9 个房间、72 个位置的低频漫反射场，为静态家具按位置和法线取样。</li><li>手机使用较小的灯光 / 天光纹理，太阳直射保持更高比例的细节。</li><li>手机渲染像素比例有上下限、负载反馈与恢复迟滞；保留画质选择和保存。</li><li>反射缓存有数量上限与淘汰；手机不分配屏幕 AO 深度附件或大尺寸 AO 缓冲。</li></ul></section><section><h2>测试与尚待验证</h2><ul class="checks"><li>219 / 219 纹理、昼夜和 HDR / depth 扩展缺失回退通过。</li><li>Chromium、Windows WebKit、微信 UA、横竖屏与设置保护通过。</li><li>建筑快照一致、屋顶无缺口、门与家具净空 / 贴墙 / 通行回归通过。</li><li>合成 CPU 压力测试触发降分辨率，解除压力后恢复；反射缓存淘汰通过。</li><li><strong>仍待：</strong>实际 iPhone 与 Android 微信的画面、发热、10 分钟持续性能及用户效果评审。</li></ul></section></div><h2>画质边界与下一轮</h2><p>本轮是实时管线首轮增强，未实施 Cycles 全屋多次反射烘焙。家具受光场基于已有贴图与固定中性反射率，辅以保守填光；关门、改变深浅墙色后不会完整重算间接光。现有模型和大面积建筑照明仍限制真实感，后续应根据本次样片评审，继续进行离线光照样板与近景模型细化。</p><p>太阳、天光和灯具原始通道保持不变，墙线 / 门洞与建筑快照不变。全局设置、自由漫游、毛坯 / A 切换保留。主应用仍是自包含单 HTML，报告资源不会由看房页自动加载。</p><details><summary>原始数据与自动检查记录</summary><ul><li><a href="before.json">优化前采集数据</a> / <a href="after.json">优化后采集数据</a></li><li><a href="v15-render-quality.json">渲染 / 昼夜 / 回退检查</a></li><li><a href="v15-mobile-compatibility.json">Chromium / WebKit 与手机视口检查</a></li><li><a href="v15-resource-policy.json">分辨率压力与反射缓存检查</a></li><li><a href="v15-decor-validation.json">建筑 / 家具 / 门 / 设置回归</a></li></ul></details><footer>2026-11-25 · 基线 38d6832 · 首轮画质评审版。截图只作 WebP 编码与等比缩小，无 AI 重绘、补光或替换画面。正式应用仍由 release 分支提供。</footer></main><script>const DATA=__DATA__;
const names={'living-day':'客厅 · 白天','living-night':'客厅 · 夜晚','master-day':'主卧 · 白天','bare-day':'毛坯 · 白天'};let device=location.hash==='#mobile'?'mobile':'pc',scene='living-day';const byId=id=>document.getElementById(id);byId('memory').textContent=DATA.resources.mobileMiB.toFixed(1)+' MiB · ↓'+DATA.resources.savingPercent.toFixed(1)+'%';for(const id of Object.keys(names)){const b=document.createElement('button');b.textContent=names[id];b.dataset.scene=id;b.onclick=()=>{scene=id;update()};byId('scenes').append(b)}for(const b of byId('devices').children)b.onclick=()=>{device=b.dataset.device;history.replaceState(null,'','#'+device);update()};function update(){const before=DATA.before.cases.find(c=>c.id===device),after=DATA.after.cases.find(c=>c.id===device),a=before.shots.find(s=>s.id===scene),b=after.shots.find(s=>s.id===scene);byId('oldImage').src=a.file;byId('newImage').src=b.file;byId('comparison').classList.toggle('mobile',device==='mobile');byId('caption').textContent=names[scene]+' · FOV '+b.metrics.fov+'° · 眼高 1.5 m · 相机位置一致；手机清晰度按负载自动调整。';for(const x of byId('devices').children)x.setAttribute('aria-pressed',String(x.dataset.device===device));for(const x of byId('scenes').children)x.setAttribute('aria-pressed',String(x.dataset.scene===scene));}byId('split').oninput=e=>byId('comparison').style.setProperty('--split',e.target.value+'%');let rows='';for(const a of DATA.before.cases){const b=DATA.after.cases.find(c=>c.id===a.id);for(const x of a.shots){const y=b.shots.find(s=>s.id===x.id);rows+='<tr><td>'+(a.id==='pc'?'PC':'手机视口')+' / '+names[x.id]+'</td><td>'+x.metrics.observedFps.toFixed(1)+'</td><td>'+y.metrics.observedFps.toFixed(1)+'</td><td>'+x.metrics.diagnostics.canvas.join('×')+' → '+y.metrics.diagnostics.canvas.join('×')+'</td></tr>'}}byId('metrics').innerHTML=rows;byId('boot').textContent='本机默认场景启动：'+DATA.before.cases.map(a=>{const b=DATA.after.cases.find(c=>c.id===a.id);return(a.id==='pc'?'PC':'手机视口')+' '+(a.bootMs/1000).toFixed(2)+' → '+(b.bootMs/1000).toFixed(2)+' 秒'}).join('；')+'。HTML：'+(DATA.resources.baselineHtmlBytes/1e6).toFixed(2)+' → '+(DATA.resources.htmlBytes/1e6).toFixed(2)+' MB。';update();</script></body></html>'''
(OUT/'index.html').write_text(page.replace('__DATA__', data), encoding='utf-8')
summary = {'resources':resource, 'checks':checks, 'physicalPhone':'not-tested', 'visualAcceptance':'pending-user-review', 'baselineCommit':'38d68328cf61d63d9e9c0bf9ce064c29fc5188a7'}
(OUT/'summary.json').write_text(json.dumps(summary, indent=2)+'\n', encoding='utf-8')
print(json.dumps({'resources':resource, 'checks':checks}, indent=2))
